class Solution:
    def generateAbbreviations(self, word: str) -> List[str]:
        res = []
        def backtrack(pos: int, curr: List[str], count: int):
            if pos == len(word):
                res.append("".join(curr) + (str(count) if count > 0 else ""))
                return
            backtrack(pos + 1, curr, count + 1)
            curr.append((str(count) if count > 0 else "") + word[pos])
            backtrack(pos + 1, curr, 0)
            curr.pop()
        backtrack(0, [], 0)
        return res

class Solution {
public:
    vector<string> generateAbbreviations(string word) {
        vector<string> res;
        string curr = "";
        backtrack(word, 0, curr, 0, res);
        return res;
    }

private:
    void backtrack(const string& word, size_t pos, string& curr, int count, vector<string>& res) {
        if (pos == word.size()) {
            res.push_back(curr + (count > 0 ? to_string(count) : ""));
            return;
        }
        backtrack(word, pos + 1, curr, count + 1, res);
        size_t len = curr.size();
        if (count > 0) curr += to_string(count);
        curr += word[pos];
        backtrack(word, pos + 1, curr, 0, res);
        curr.resize(len);
    }
};

class Solution {
    public List<String> generateAbbreviations(String word) {
        List<String> res = new ArrayList<>();
        backtrack(word, 0, new StringBuilder(), 0, res);
        return res;
    }

    private void backtrack(String word, int pos, StringBuilder curr, int count, List<String> res) {
        int len = curr.length();
        if (pos == word.length()) {
            if (count > 0) curr.append(count);
            res.add(curr.toString());
            curr.setLength(len);
            return;
        }
        backtrack(word, pos + 1, curr, count + 1, res);
        if (count > 0) curr.append(count);
        curr.append(word.charAt(pos));
        backtrack(word, pos + 1, curr, 0, res);
        curr.setLength(len);
    }
}

