var generateAbbreviations = function(word) {
    const res = [];
    function backtrack(pos, curr, count) {
        if (pos === word.length) {
            res.push(curr.join('') + (count > 0 ? String(count) : ''));
            return;
        }
        backtrack(pos + 1, curr, count + 1);
        curr.push((count > 0 ? String(count) : '') + word[pos]);
        backtrack(pos + 1, curr, 0);
        curr.pop();
    }
    backtrack(0, [], 0);
    return res;
};
